import {lessons} from './course.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',learn:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H3V4Zm9 3a3 3 0 0 1 3-3h5v15h-5a4 4 0 0 0-3 2',exam:'M9 3h6v3H9zM7 4H5v17h14V4h-2M8 11l2 2 5-5M8 17h7',sounds:'M3 9v6m4-10v14m5-17v20m5-17v14m4-10v6',practice:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z',translate:'M3 5h12M9 3v2m-4 3c1 4 4 7 8 9m-1-12C11 12 7 16 3 18m11 3 4-11 4 11m-6.6-4h5.2',captions:'M3 5h18v14H3zM10 10a3 3 0 1 0 0 4m9-4a3 3 0 1 0 0 4',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16m-6-6 6 6-6 6',play:'m9 5 11 7-11 7Z',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',spark:'m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6Z',headphones:'M4 14V11a8 8 0 0 1 16 0v3M4 12H2v8h5v-8Zm16 0h2v8h-5v-8Z',close:'m6 6 12 12M6 18 18 6',flip:'M4 8h13l-3-3m6 11H7l3 3M3 12a9 9 0 0 1 16-6m2 6a9 9 0 0 1-16 6'};
export const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const waves=()=>Array.from({length:23},(_,i)=>`<i style="--bar:${[12,20,32,18,38,52,34,62,44,70,52,82,60,44,68,40,56,30,42,24,30,16,10][i]}px;--delay:${i*35}ms"></i>`).join('');
const words=[...lessons.flatMap(lesson=>lesson.words.map(([de,en])=>({de,en,lesson:lesson.title}))),{de:'die Vorfreude',en:'the joy of looking forward to something',lesson:'A word to take with you'}];
export function makeReviewDeck(source,random=Math.random,limit=10){const deck=[...source];for(let i=deck.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}return deck.slice(0,limit);}
export function remainingSeconds(timer,now=Date.now()){return Math.max(0,timer.running?Math.ceil((timer.endsAt-now)/1000):timer.remaining);}

export function homeDashboard({progress,saved}){
 const next=lessons.find(lesson=>!progress.includes(lesson.id))||lessons[0],percent=Math.round(progress.length/lessons.length*100);
 return `<div class="dashboard-heading"><div><div class="eyebrow">a few words, a few mistakes, a little progress.</div><h1>A little German.<br class="mobile-break"> A bookful of possibilities.</h1></div><span class="date-chip" data-studio-date></span></div>
 <div class="home-bento"><section class="launch-card"><div class="launch-copy"><span class="live-label"><span></span> THIS IS WHERE THE STORY STARTS</span><h2>A new language.<br><em>A messy, lovely beginning.</em></h2><p>No perfect handwriting. No perfect accent. Just you, a few words, and a place to begin.</p><div class="row"><button class="btn launch-btn" data-lesson="${next.id}">${progress.length?'Continue learning':'Start with Hallo'} ${icon('arrow',18)}</button><a class="launch-link" href="#sounds">Explore the sounds ${icon('headphones',17)}</a></div><div class="launch-tags"><span>No German needed to start</span><span>Mistakes welcome here.</span></div></div><figure class="journal-illustration"><img src="illustrations/black-forest-ink.png" width="1254" height="1254" alt="An original ink drawing of a half-timbered German village at the edge of a fir forest" loading="lazy" decoding="async"><figcaption>somewhere between a first word<br>and a whole new world.</figcaption></figure><div class="sonic-object"><div class="sonic-orbit orbit-a"></div><div class="sonic-orbit orbit-b"></div><button class="chrome-letter" data-speak="Ü" aria-label="Hear the German letter Ü"><span>ü</span></button><span class="floating-label sonic-top">/yː/ · ROUND YOUR LIPS</span><div class="sonic-player"><button class="sound" data-speak="grün" aria-label="Listen to grün">${icon('play',16)}</button><span><strong lang="de">grün</strong><small>green · human recording</small></span><div class="mini-wave" aria-hidden="true">${waves()}</div></div><span class="sonic-foot">TAP THE Ü. HEAR SOMETHING NEW.</span></div></section>
 <section class="focus-card"><div class="widget-label">${icon('clock',17)} a little time for this? <span class="little-star">✦</span></div><h2>Small steps.<br>Real progress.</h2><p>Set aside a little time.<br>Your future self says danke.</p><div class="focus-dial" data-focus-dial><div><strong data-focus-time>10:00</strong><span data-focus-state>Your focus session</span></div></div><div class="focus-options" role="group" aria-label="Focus session length">${[5,10,15].map(n=>`<button data-studio="duration" data-minutes="${n}" aria-pressed="${n===10}">${n} min</button>`).join('')}</div><div class="focus-actions"><button class="btn" data-studio="timer" data-focus-button>Start session ${icon('play',15)}</button><button class="pill" data-studio="reset-timer" aria-label="Reset focus timer">↺</button></div><small>Keep learning while the timer runs.</small></section>
 <section class="journey-card"><div class="widget-label">${icon('learn',18)} pages you’ve made your own <a href="#learn" aria-label="Open the learning path">↗</a></div><div class="journey-content"><div class="journey-ring" style="--progress:${percent}%"><strong>${progress.length}<small>/12</small></strong></div><div><h3>${progress.length?'Keep the momentum.':'Everyone starts somewhere.'}</h3><p>${progress.length} of 12 lessons completed</p><a class="text-link" href="#learn">Explore your learning path ${icon('arrow',15)}</a></div></div><div class="journey-track" aria-label="${progress.length} of 12 lessons completed">${lessons.map((l,i)=>`<button data-lesson="${l.id}" class="${progress.includes(l.id)?'done':''}" aria-label="Open lesson ${i+1}: ${esc(l.title)}">${progress.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</button>`).join('')}</div></section>
 <section class="exam-portal"><div class="widget-label">${icon('exam',18)} THE VERY IMPORTANT REVISION PILE <span class="portal-badge">EXAM</span></div><h2>Your notes.<br>Now, your advantage.</h2><p>14 grammar guides, 307 exercises, and your fully worked model paper.</p><div class="row"><a class="btn" href="#exam">Enter exam prep ${icon('arrow',16)}</a><a class="text-link" href="#exam-model">Model paper ↗</a></div><div class="portal-watermark" aria-hidden="true">A1</div></section>
 <section class="next-card"><div class="widget-label">a good next page → <span>${String(lessons.indexOf(next)+1).padStart(2,'0')} / 12</span></div><div class="next-icon">${icon(lessons.indexOf(next)<2?'sounds':'learn',30)}</div><h3>${esc(next.title)}</h3><p>${esc(next.subtitle)}</p><div class="next-meta">${icon('clock',14)} ${next.minutes} min <span>·</span> Listen + practise</div><button class="btn secondary" data-lesson="${next.id}">${progress.length?'Continue lesson':'Open your first lesson'} ${icon('arrow',17)}</button></section>
 <section class="word-day card"><div class="widget-label">found a lovely word… ${icon('spark',18)}</div><h3 lang="de">die Vorfreude</h3><p>The joy of looking forward to something.</p><div class="word-day-bottom"><button class="sound" data-speak="die Vorfreude" aria-label="Listen to die Vorfreude">${icon('play',16)}</button><button class="save" data-custom-save="die Vorfreude" aria-pressed="${saved.includes('die Vorfreude')}">♡ Save word</button></div></section>
 <a class="mini-tool tool-cyan" href="#practice"><div class="mini-tool-icon">${icon('practice',26)}</div><h3>Make it stick.</h3><p>Flip a card. Recall a word.<br>Build a little confidence.</p><span>Flashcards & saved words <b data-saved-count>${saved.length}</b> ↗</span></a>
 <a class="mini-tool tool-coral" href="#translate"><div class="mini-tool-icon">${icon('translate',26)}</div><h3>Bridge the gap.</h3><p>A thought in English.<br>A new sentence in German.</p><span>Open the translator ↗</span></a>
 <a class="mini-tool tool-amber" href="#captions"><div class="mini-tool-icon">${icon('captions',26)}</div><h3>Read the feeling.</h3><p>Words, speakers, and sounds.<br>A more accessible conversation.</p><span>Explore SDH captions ↗</span></a></div><div class="home-signoff"><span>written slowly. learned a little at a time.</span><span>German. At your pace. ${icon('spark',14)}</span></div>`;
}
export function reviewMarkup(){return `<section class="review-studio" aria-labelledby="review-title"><div class="review-heading"><div><div class="eyebrow">RECALL LAB</div><h2 id="review-title">Don’t just read it. Remember it.</h2><p>A short round of up to ten cards. Reveal the meaning, then rate your own recall.</p></div><label class="field">Review deck<select id="review-source"><option value="all">Everyday words</option><option value="saved">My saved words</option></select></label></div><div id="review-body"></div></section>`;}
let api,review,timer={minutes:10,remaining:600,running:false,endsAt:0},timerInterval,finished=false,commandIndex=0,commandResults=[];
const routes=[['home','Overview','Your dashboard and focus timer'],['learn','Learning path','12 lessons for your first conversations'],['exam','Semester exam','Study guides, vocabulary and 307 exercises'],['exam-model','Model paper & answers','All six questions with worked answers'],['sounds','Sound studio','Native alphabet, spelling and speaking'],['practice','Practice & words','Recall cards and your saved collection'],['translate','Translator','English ↔ German'],['captions','Caption studio','Accessible captions, tone and sounds']];
const commandItems=[...routes.map(([id,title,detail])=>({kind:'route',id,title,detail})),...lessons.map(lesson=>({kind:'lesson',id:lesson.id,title:lesson.title,detail:`Lesson · ${lesson.minutes} min · ${lesson.category}`})),...words.map(word=>({kind:'word',id:word.de,title:word.de,detail:`${word.en} · Practise in Sound studio`}))];
export function searchCommands(query){const q=query.toLocaleLowerCase().trim();return commandItems.filter(item=>!q||`${item.title} ${item.detail}`.toLocaleLowerCase().includes(q)).slice(0,q?14:8);}
function renderCommands(){const input=document.querySelector('#command-search');commandResults=searchCommands(input.value);commandIndex=0;document.querySelector('#command-results').innerHTML=commandResults.length?commandResults.map((item,i)=>`<button id="command-result-${i}" data-command-index="${i}" role="option" aria-selected="${i===0}"><span class="command-icon">${icon(item.kind==='route'?item.id:item.kind==='word'?'sounds':'learn',18)}</span><span><strong>${esc(item.title)}</strong><small>${esc(item.detail)}</small></span><span class="command-enter">↵</span></button>`).join(''):'<p class="command-empty">No matches. Try “exam”, “sounds”, or “hello”.</p>';syncCommandSelection();}
function syncCommandSelection(){document.querySelectorAll('[data-command-index]').forEach((el,i)=>el.setAttribute('aria-selected',String(i===commandIndex)));const input=document.querySelector('#command-search');if(commandResults.length)input.setAttribute('aria-activedescendant','command-result-'+commandIndex);else input.removeAttribute('aria-activedescendant');}
function openCommands(){const dialog=document.querySelector('#command-dialog');dialog.showModal();document.querySelector('#command-search').value='';renderCommands();document.querySelector('#command-search').focus();}
function jumpCommand(index){const item=commandResults[index];if(!item)return;document.querySelector('#command-dialog').close();if(item.kind==='lesson')api.openLesson(item.id);else if(item.kind==='word')api.practiceWord(item.id);else api.navigate(item.id);}
function updateTimer(){const seconds=remainingSeconds(timer);document.querySelectorAll('[data-focus-time]').forEach(el=>el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`);document.querySelector('[data-focus-dial]')?.style.setProperty('--focus-progress',(1-seconds/(timer.minutes*60))*100+'%');const state=document.querySelector('[data-focus-state]');if(state)state.textContent=finished?'Session complete':timer.running?'You’ve got this.':seconds===timer.minutes*60?'Your focus session':'Paused. Take your time.';const button=document.querySelector('[data-focus-button]');if(button)button.innerHTML=(finished?'Start again':timer.running?'Pause session':seconds===timer.minutes*60?'Start session':'Resume session')+' '+icon(timer.running?'clock':'play',15);document.querySelectorAll('[data-minutes]').forEach(button=>{button.setAttribute('aria-pressed',String(Number(button.dataset.minutes)===timer.minutes));button.disabled=timer.running;});if(timer.running&&seconds===0){timer.running=false;timer.remaining=0;finished=true;clearInterval(timerInterval);updateTimer();api.toast('Wunderbar! Your focus session is complete. Take a little break.');}}
function startTimer(){if(timer.running){timer.remaining=remainingSeconds(timer);timer.running=false;clearInterval(timerInterval);}else{if(!timer.remaining||finished){timer.remaining=timer.minutes*60;finished=false;}timer.endsAt=Date.now()+timer.remaining*1000;timer.running=true;clearInterval(timerInterval);timerInterval=setInterval(updateTimer,250);}updateTimer();}
function beginReview(source){const pool=source==='saved'?words.filter(word=>api.getSaved().includes(word.de)):words;review={source,deck:makeReviewDeck(pool),index:0,revealed:false,recalled:0,again:[]};renderReview();}
function renderReview(){const root=document.querySelector('#review-body');if(!root||!review)return;const {deck,index}=review;if(!deck.length){root.innerHTML=`<div class="review-empty">${icon('practice',32)}<h3>A collection starts with one word.</h3><p>Save some everyday words below, then refresh this deck.</p><div class="row" style="justify-content:center"><button class="btn" data-studio="review-all">Try everyday words ${icon('arrow',16)}</button><button class="pill" data-studio="new-review">Refresh saved deck ↻</button></div></div>`;return;}if(index>=deck.length){root.innerHTML=`<div class="review-summary">${icon('spark',36)}<div class="eyebrow">ROUND COMPLETE</div><h3>One step closer.</h3><p>You marked ${review.recalled} of ${deck.length} cards as recalled.<br>${review.again.length?'Give the tricky ones another moment.':'Say one of them out loud before you go.'}</p><div class="row">${review.again.length?'<button class="btn" data-studio="review-missed">Review tricky cards ↻</button>':''}<button class="pill" data-studio="new-review">New round ↗</button></div><small>This is your self-review, not a pronunciation score.</small></div>`;return;}const word=deck[index];root.innerHTML=`<div class="review-topline"><span>CARD ${String(index+1).padStart(2,'0')} / ${String(deck.length).padStart(2,'0')}</span><span>${esc(word.lesson)}</span></div><div class="recall-progress" aria-label="Card ${index+1} of ${deck.length}">${deck.map((_,i)=>`<i class="${i<index?'complete':i===index?'current':''}"></i>`).join('')}</div><div class="recall-card ${review.revealed?'is-revealed':''}"><span class="recall-language">DEUTSCH → ENGLISH</span><h3 lang="de">${esc(word.de)}</h3><button class="sound" data-speak="${esc(word.de)}" aria-label="Listen to ${esc(word.de)}">${icon('play',18)}</button><button class="recall-flip" data-studio="flip" aria-expanded="${review.revealed}" aria-controls="recall-meaning">${review.revealed?'Hide meaning':'Reveal meaning'} ${icon('flip',17)}</button><p id="recall-meaning" ${review.revealed?'':'hidden'}>${esc(word.en)}</p></div><div class="recall-actions"><button class="pill" data-studio="review-again" ${review.revealed?'':'disabled'}>↻ Practise again</button><span>How did you do?</span><button class="btn" data-studio="review-known" ${review.revealed?'':'disabled'}>${icon('check',17)} Got it</button></div>`;}
export function refreshStudio(){const date=document.querySelector('[data-studio-date]');if(date)date.textContent=new Intl.DateTimeFormat('en',{weekday:'short',day:'numeric',month:'short'}).format(new Date());const progress=api?.getProgress()||[];document.querySelectorAll('[data-course-progress]').forEach(el=>el.textContent=progress.length+'/12 lessons');document.querySelectorAll('[data-course-bar]').forEach(el=>el.style.width=progress.length/lessons.length*100+'%');updateTimer();}
export function mountStudio(callbacks){api=callbacks;try{const minutes=Number(localStorage.getItem('wortreise-focus-minutes'));if([5,10,15].includes(minutes))timer={minutes,remaining:minutes*60,running:false,endsAt:0};}catch{}
 const placeTheme=()=>{const toggle=document.querySelector('#theme-toggle');if(toggle)(innerWidth>960?document.querySelector('.header-right'):document.querySelector('aside')).append(toggle);};placeTheme();document.addEventListener('DOMContentLoaded',placeTheme);window.addEventListener('resize',placeTheme);
 document.querySelectorAll('aside [data-nav]').forEach(link=>{const label=link.querySelector('span').textContent;link.innerHTML=`<span class="nav-icon">${icon(link.dataset.nav,20)}</span><span>${esc(label)}</span><i class="nav-dot"></i>`;});
 document.body.insertAdjacentHTML('beforeend',`<dialog id="command-dialog" aria-labelledby="command-title"><div class="command-head"><span>${icon('search',22)}</span><label class="sr-only" id="command-title" for="command-search">Search lessons, tools and words</label><input id="command-search" role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls="command-results" autocomplete="off" placeholder="Where would you like to go?"><button class="command-close" data-studio="close-search" aria-label="Close quick search">Esc</button></div><div class="command-caption">SOMEWHERE IN THESE NOTEBOOKS…</div><div id="command-results" role="listbox" aria-label="Search results"></div><div class="command-footer"><span>↑ ↓ to explore <b>↵</b> to open</span><span>WORTREISE / FIND A PAGE</span></div></dialog>`);
 document.querySelector('#command-search').addEventListener('input',renderCommands);
 document.querySelector('#command-search').addEventListener('keydown',event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(!commandResults.length)return;commandIndex=(commandIndex+(event.key==='ArrowDown'?1:-1)+commandResults.length)%commandResults.length;syncCommandSelection();document.querySelector('#command-result-'+commandIndex)?.scrollIntoView({block:'nearest'});}if(event.key==='Enter'){event.preventDefault();jumpCommand(commandIndex);}});
 document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(document.querySelector('#command-dialog').open)document.querySelector('#command-dialog').close();else if(!document.querySelector('dialog[open]'))openCommands();}});
 document.addEventListener('change',event=>{if(event.target.id==='review-source')beginReview(event.target.value);});
 document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.commandIndex!==undefined){jumpCommand(Number(button.dataset.commandIndex));return;}const action=button.dataset.studio;if(!action)return;if(action==='search')openCommands();if(action==='close-search')document.querySelector('#command-dialog').close();if(action==='timer')startTimer();if(action==='reset-timer'){clearInterval(timerInterval);timer.running=false;timer.remaining=timer.minutes*60;finished=false;updateTimer();}if(action==='duration'){clearInterval(timerInterval);timer.minutes=Number(button.dataset.minutes);timer.remaining=timer.minutes*60;timer.running=false;finished=false;try{localStorage.setItem('wortreise-focus-minutes',timer.minutes);}catch{}updateTimer();}if(action==='flip'){review.revealed=!review.revealed;renderReview();document.querySelector('[data-studio=flip]')?.focus();}if(action==='review-known'||action==='review-again'){if(!review?.revealed)return;if(action==='review-known')review.recalled++;else review.again.push(review.deck[review.index]);review.index++;review.revealed=false;renderReview();document.querySelector('[data-studio=flip], [data-studio=review-missed], [data-studio=new-review]')?.focus();}if(action==='new-review')beginReview(document.querySelector('#review-source').value);if(action==='review-all'){document.querySelector('#review-source').value='all';beginReview('all');}if(action==='review-missed'){review={source:review.source,deck:[...review.again],index:0,revealed:false,recalled:0,again:[]};renderReview();}if(action==='lesson-filter'){document.querySelectorAll('[data-lesson-filter]').forEach(el=>el.setAttribute('aria-pressed',String(el===button)));const filter=button.dataset.lessonFilter;let shown=0;document.querySelectorAll('#learn .lesson-card').forEach((card,i)=>{card.hidden=filter==='remaining'&&api.getProgress().includes(lessons[i].id)||filter==='complete'&&!api.getProgress().includes(lessons[i].id);if(!card.hidden)shown++;});document.querySelector('#lesson-filter-empty').hidden=shown>0;}});
 beginReview('all');refreshStudio();
}
